'use strict';
let state, token, busy=false, view='overview', selected=null, customerTab='conversation', query='', caseFilter='all', statusFilter='all', taskOwner='all', authPoll=null;
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=value=>esc(t(value));
const today=()=>state.now.slice(0,10);
const rows=(table,id)=>(state[table]||[]).filter(r=>r.invoice_id===id);
const money=value=>new Intl.NumberFormat(language==='ar'?'ar-SA':'en-SA',{minimumFractionDigits:2,maximumFractionDigits:2}).format((value||0)/100);
const currency=value=>`${language==='ar'?'ر.س':'SAR'} ${money(value)}`;
const num=value=>new Intl.NumberFormat(language==='ar'?'ar-SA':'en').format(value||0);
const date=value=>value?new Date(value.slice(0,10)+'T12:00:00').toLocaleDateString(language==='ar'?'ar-SA-u-ca-gregory':'en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const sum=(items,key)=>items.reduce((a,r)=>a+Number(r[key]||0),0);
const inv=id=>state.invoices.find(r=>r.invoice_id===id);
const profile=invoice=>(state.profiles||[]).find(r=>r.customer_id===invoice.customer_id)||{};
const name=invoice=>invoice?(language==='ar'?(profile(invoice).name_ar||invoice.customer_name):invoice.customer_name):'—';
const teamName=id=>{const person=(state.team||[]).find(p=>p.id===id);return person?localized(person,'name'):t('Unassigned');};
const actor=()=>state.settings?.current_actor||'collector_sara';
const allocated=p=>sum((state.promise_allocations||[]).filter(a=>a.promise_id===p.promise_id),'amount_minor');
const isActive=p=>['active','partially_fulfilled','missed'].includes(p.status);
const iconPaths={overview:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',collections:'M4 5h16v15H4zM8 2v6m8-6v6M8 12h8m-8 4h5',promises:'M12 3a9 9 0 1 0 9 9M12 7v5l4 2M16 3l2 2 4-4',tasks:'M9 5h12M9 12h12M9 19h12M3 5l1 1 2-3M3 12l1 1 2-3M3 19l1 1 2-3',approvals:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',analytics:'M4 20V10m8 10V4m8 16v-7M2 22h20',feedback:'M3 4h18v13H9l-6 4zM7 8h10M7 12h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',studio:'M9 3h6M10 3v6l-6 10a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2L14 9V3M7 15h10',arrow:'M5 12h14M14 7l5 5-5 5',check:'M5 12l4 4L19 6',refresh:'M20 7a9 9 0 1 0 1 9M20 3v5h-5',close:'M5 5l14 14M19 5L5 19',menu:'M3 6h18M3 12h18M3 18h18'};
const icon=key=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[key]||iconPaths.arrow}"/></svg>`;
const button=(text,action,id='',type='secondary',extra='')=>`<button class="${type}" data-action="${action}" data-id="${esc(id)}" ${extra}>${tx(text)}</button>`;
const navButton=(text,target,type='text-button')=>`<button class="${type}" data-nav="${target}">${tx(text)} ${icon('arrow')}</button>`;
const badge=(value,tone='')=>`<span class="badge ${esc(tone||toneFor(value))}">${tx(value)}</span>`;
function toneFor(value){return ['fulfilled','approved','processed','Settled','Promise recorded','sent'].includes(value)?'green':['missed','Missed promise','rejected'].includes(value)?'red':['pending_review','pending_credit','Disputed','Verify payment','Needs review','partially_fulfilled','Part paid'].includes(value)?'amber':'';}
function caseStatus(invoice){
 if(invoice.status==='settled'||invoice.outstanding_minor===0)return 'Settled';
 if(rows('disputes',invoice.invoice_id).some(r=>['pending_review','pending_credit'].includes(r.status)))return 'Disputed';
 if(rows('tasks',invoice.invoice_id).some(r=>r.status==='pending'&&r.task_type==='payment_verification'))return 'Verify payment';
 if(rows('promises',invoice.invoice_id).some(r=>r.status==='missed'))return 'Missed promise';
 if(rows('promises',invoice.invoice_id).some(r=>r.status==='partially_fulfilled'))return 'Part paid';
 if(rows('promises',invoice.invoice_id).some(r=>r.status==='active'))return 'Promise recorded';
 if(rows('tasks',invoice.invoice_id).some(r=>r.status==='pending'&&['human_review','clarification','dispute_review'].includes(r.task_type))||(state.reviews||[]).some(r=>['awaiting_clarification','needs_human_review'].includes(r.status)&&rows('messages',invoice.invoice_id).some(m=>m.message_id===r.message_id)))return 'Needs review';
 if(invoice.outstanding_minor<invoice.original_minor){const cash=rows('audit_events',invoice.invoice_id).some(e=>{if(e.action!=='balance_verified')return false;try{return JSON.parse(e.details_json).payment_minor>0;}catch{return false;}});return cash?'Part paid':'Adjusted';}
 return 'Overdue';
}
const empty=text=>`<div class="empty"><span class="empty-symbol">${icon('check')}</span><p>${tx(text)}</p></div>`;
const heading=(title,subtitle,action='')=>`<div class="view-heading"><div><span class="eyebrow">${tx('Discovery edition')}</span><h1>${tx(title)}</h1><p>${tx(subtitle)}</p></div>${action}</div>`;
const panel=(title,subtitle,content,action='',classes='')=>`<section class="panel ${classes}"><div class="panel-head"><div><h2>${tx(title)}</h2>${subtitle?`<p>${tx(subtitle)}</p>`:''}</div>${action}</div><div class="panel-body">${content}</div></section>`;
const stat=(title,value,help,tone='')=>`<article class="stat ${tone}"><span>${tx(title)}</span><strong>${esc(value)}</strong><small>${tx(help)}</small></article>`;
const accountLink=invoice=>`<button class="account-link" data-action="account" data-id="${esc(invoice.invoice_id)}"><span class="avatar">${esc(name(invoice).slice(0,1))}</span><span><strong>${esc(name(invoice))}</strong><small>${esc(invoice.invoice_id)} · ${tx(profile(invoice).segment||'Synthetic portfolio')}</small></span></button>`;
function notice(message,error=false){$('notice').hidden=false;$('notice').className='toast'+(error?' error':'');$('notice').textContent=message;const dialog=$('actionDialog').open?$('actionDialog'):$('customerDialog').open?$('customerDialog'):null;if(dialog){let status=dialog.querySelector('.dialog-status');if(!status){status=document.createElement('div');status.setAttribute('role','status');status.setAttribute('aria-live','polite');dialog.insertBefore(status,dialog.children[1]||null);}status.className='dialog-status'+(error?' error':'');status.textContent=message;}clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('notice').hidden=true,error?12000:7000);}
async function refresh(){const response=await fetch('/api/state');if(!response.ok)throw new Error(t('Could not load workspace'));state=await response.json();render();if($('customerDialog').open&&selected)renderCustomer();}
function render(){
 document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';document.title=language==='ar'?'متابع · مساحة التحصيل':'Mutabi · Collections workspace';
 const names={overview:'Overview',collections:'Collections',promises:'Promises',tasks:'Tasks',approvals:'Approvals',analytics:'Analytics',impact:'Impact calculator',feedback:'Feedback',settings:'Settings',studio:'Demo studio'};
 const counts={tasks:state.tasks.filter(r=>r.status==='pending').length,approvals:state.drafts.filter(r=>r.status==='awaiting_approval').length};
 $('app').innerHTML=`<aside class="rail" id="navigation"><a class="brand" href="#overview"><span class="brand-mark">m</span><span>${language==='ar'?'متابع':'mutabi'}<b>.</b></span></a><button class="rail-close icon-button" data-action="menu" aria-label="${tx('Close navigation')}">${icon('close')}</button><div class="workspace-id"><span class="online-dot"></span><div><strong>${tx('Discovery edition')}</strong><small>${tx('Synthetic workspace')}</small></div><span class="edition">01</span></div><span class="nav-label">${tx('Your workspace')}</span><nav aria-label="${tx('Your workspace')}">${Object.entries(names).map(([id,text])=>`<button data-nav="${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${tx(text)}</span>${counts[id]?`<span class="nav-count">${num(counts[id])}</span>`:''}</button>`).join('')}</nav><div class="rail-bottom"><div class="rail-prompt"><span>${tx('Cash visibility starts with reliable commitments.')}</span>${navButton('Try this journey','studio')}</div><span class="rail-status"><span class="online-dot"></span>${tx('Session isolated')}</span><small>${tx('Simulated delivery')} · SAR</small></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="menu" aria-controls="navigation" aria-expanded="false" aria-label="${tx('Show navigation')}">${icon('menu')}</button><span>${tx('Your workspace')}</span><span>/</span><strong>${tx(names[view])}</strong></div><div class="top-actions"><span class="clock-label">${date(state.now)}</span><button class="language-button" data-action="language">${language==='ar'?'English':'العربية'}</button><button class="secondary compact" data-action="feedback">${icon('feedback')}${tx('Share feedback')}</button><span class="avatar user" title="${esc(teamName(actor()))}">${esc(teamName(actor()).slice(0,1))}</span></div></header><main id="content" tabindex="-1"><div class="synthetic-banner"><span class="online-dot"></span>${tx('All customer data is synthetic. No real messages are sent.')}<button data-nav="settings">${tx('View assumptions')}</button></div><div id="viewContent">${({overview:overviewView,collections:collectionsView,promises:promisesView,tasks:tasksView,approvals:approvalsView,analytics:analyticsView,impact:impactView,feedback:feedbackView,settings:settingsView,studio:studioView}[view]||overviewView)()}</div><footer><span>© 2026 ${language==='ar'?'متابع':'Mutabi'} · ${tx('Discovery edition')}</span><span>${tx('No real customer contacted')} · ${tx('Live AI is optional')}</span></footer></main></div>`;
 setBusy(busy);if(state.chatgpt?.pending)pollAuth();
}
function agingData(){const buckets=[['Current',0],['1–30 days',0],['31–60 days',0],['61–90 days',0],['90+ days',0]];state.invoices.forEach(i=>{const days=Math.floor((new Date(today())-new Date(i.due_date))/86400000);buckets[days<=0?0:days<=30?1:days<=60?2:days<=90?3:4][1]+=i.outstanding_minor;});return buckets;}
function agingChart(){const data=agingData(),max=Math.max(...data.map(r=>r[1]),1);return `<div class="aging-chart">${data.map(([label,value],index)=>`<div class="aging-row"><span>${tx(label)}</span><svg viewBox="0 0 300 20" preserveAspectRatio="none" role="img" aria-label="${tx(label)}: ${esc(currency(value))}"><rect width="300" height="16" y="2" rx="3" fill="#edf1ed"/><rect width="${Math.max(value/max*300,value?3:0)}" height="16" y="2" rx="3" fill="${['#94bcb0','#287a69','#175e50','#d7a850','#aa6945'][index]}"/></svg><strong>${currency(value)}</strong></div>`).join('')}</div>`;}
function activityContent(events){return events.length?`<div class="timeline">${events.slice(-7).reverse().map(e=>{let details={};try{details=JSON.parse(e.details_json||'{}');}catch{}return `<div class="timeline-row"><span class="timeline-dot"></span><div><strong>${esc(eventTitle(e.action))}</strong><p dir="auto">${esc(details.reason||t(details.status)||details.message_id||e.invoice_id||t('Saved to this workspace.'))}</p><small>${date(e.occurred_at)} · ${esc((e.occurred_at||'').slice(11,16))}</small></div>${e.invoice_id?button('View','account',e.invoice_id,'text-button'):''}</div>`;}).join('')}</div>`:empty('No activity yet.');}
function eventTitle(action){const labels={message_completed:'Review result',message_interpreted:'Demo interpretation',promise_recorded:'Promise recorded',draft_created:'Draft text',draft_approved:'Approve',message_sent:'Simulated delivery',balance_verified:'Balance verified',promise_amended:'Amend commitment',payment_allocated:'Allocate payment',note_added:'Internal note',dispute_resolved:'Resolve dispute',task_completed:'Complete task',manual_review_confirmed:'Manual review'};return t(labels[action]||action.replace(/_/g,' '));}
function overviewView(){
 const active=state.promises.filter(isActive),pending=state.tasks.filter(t=>t.status==='pending'),balance=sum(state.invoices,'outstanding_minor');
 const attention=state.invoices.filter(i=>i.outstanding_minor>0).sort((a,b)=>{const ranks={'Disputed':4,'Verify payment':3,'Needs review':3,'Missed promise':2};return (ranks[caseStatus(b)]||0)-(ranks[caseStatus(a)]||0)||b.outstanding_minor-a.outstanding_minor;}).slice(0,5);
 const end=new Date(today());end.setDate(end.getDate()+7);const upcoming=active.filter(p=>p.promised_date>=today()&&p.promised_date<=end.toISOString().slice(0,10)).sort((a,b)=>a.promised_date.localeCompare(b.promised_date));
 return heading('Follow up with confidence.','A clear view of your receivables, commitments, and the next best action.',button('Refresh','refresh','','secondary'))+`<div class="stats">${stat('Outstanding balance',currency(balance),'Across synthetic invoices','accent')}${stat('Active commitments',num(active.length),'Remaining promised amount')}${stat('Tasks due',num(pending.filter(t=>t.due_date<=today()).length),'Due on or before workspace date')}${stat('Awaiting approval',num(state.drafts.filter(d=>d.status==='awaiting_approval').length),'Employee review before delivery')}</div><div class="overview-grid">${panel('Needs attention','The work that matters today',attention.length?`<div class="attention-list">${attention.map(i=>`<div class="attention-row">${accountLink(i)}<div class="align-end"><strong>${currency(i.outstanding_minor)}</strong>${badge(caseStatus(i))}</div>${button('Open','account',i.invoice_id,'text-button')}</div>`).join('')}</div>`:empty('Nothing urgent right now.'),navButton('View all collections','collections'))}${panel('Receivables aging','Days past invoice due date',agingChart())}${panel('Upcoming commitments','Next seven days from the workspace clock',upcoming.length?upcoming.slice(0,6).map(p=>`<div class="commitment-row"><div><strong>${esc(name(inv(p.invoice_id)))}</strong><small>${date(p.promised_date)}</small></div><strong>${currency(Math.max(p.amount_minor-allocated(p),0))}</strong>${button('View','account',p.invoice_id,'text-button')}</div>`).join(''):empty('No upcoming commitments.'))}${panel('Recent activity','',activityContent(state.audit_events))}</div><div class="journey-banner"><div><span class="eyebrow">${tx('Quick start')}</span><h2>${tx('Try a complete collection journey')}</h2><p>${tx('Choose a story, review a reply, and see what happens next.')}</p></div>${navButton('Open demo studio','studio','primary')}</div>`;
}
function filterSelect(id,label,choices,value){return `<label class="filter-label"><span class="sr-only">${tx(label)}</span><select id="${id}">${choices.map(([v,text])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${tx(text)}</option>`).join('')}</select></label>`;}
function collectionsView(){const cases=state.invoices.filter(i=>(name(i)+' '+i.customer_name+' '+i.invoice_id).toLowerCase().includes(query.toLowerCase())&&(caseFilter==='all'||caseStatus(i)===caseFilter));const unassigned=state.messages.filter(m=>!m.invoice_id);return heading('Collection worklist','Review the account, understand the reply, and decide the next action.',`<a class="secondary" href="/api/export?format=csv&dataset=invoices">${tx('Export invoices')}</a>`)+`<div class="toolbar"><div class="search-wrap">${icon('collections')}<input type="search" id="caseSearch" value="${esc(query)}" placeholder="${tx('Search customer or invoice…')}" aria-label="${tx('Search')}"></div>${filterSelect('caseFilter','Status',[['all','All cases'],...['Overdue','Needs review','Disputed','Verify payment','Missed promise','Promise recorded','Settled','Part paid','Adjusted'].map(v=>[v,v])],caseFilter)}<span class="subtle">${num(cases.length)} / ${num(state.invoices.length)}</span></div><section class="panel"><div class="table-scroll"><table><thead><tr>${['Customer','Balance','Due date','Status','Owner',''].map(v=>`<th>${tx(v)}</th>`).join('')}</tr></thead><tbody>${cases.map(i=>`<tr><td>${accountLink(i)}</td><td class="numeric"><strong>${currency(i.outstanding_minor)}</strong><small>${tx('Original invoice')} ${currency(i.original_minor)}</small></td><td>${date(i.due_date)}</td><td>${badge(caseStatus(i))}</td><td><span class="owner-cell"><span class="mini-avatar">${esc(teamName(profile(i).owner).slice(0,1))}</span>${esc(teamName(profile(i).owner))}</span></td><td>${button('Open account','account',i.invoice_id,'text-button')}</td></tr>`).join('')}</tbody></table>${!cases.length?empty('No cases match your filters.'):''}</div></section>${panel('Unassigned replies','Link the correct invoice before recording a commitment.',unassigned.length?unassigned.map(m=>`<div class="message"><div class="message-meta"><code>${esc(m.message_id)}</code>${date(m.received_at)}</div><p dir="auto">${esc(m.text)}</p>${button('Assign invoice','assign-message',m.message_id)}</div>`).join(''):empty('No replies yet.'))}`;}
function promisesView(){const promises=state.promises.filter(p=>statusFilter==='all'||p.status===statusFilter),active=state.promises.filter(isActive);return heading('Commitment register','Track each promised installment independently of the invoice balance.')+`<div class="stats three">${stat('Committed',currency(sum(active,'amount_minor')),'Active commitments')}${stat('Allocated',currency(sum(state.promise_allocations||[],'amount_minor')),'Verified payments')}${stat('Remaining',currency(active.reduce((s,p)=>s+Math.max(p.amount_minor-allocated(p),0),0)),'Remaining promised amount')}</div><div class="toolbar">${filterSelect('statusFilter','Status',[['all','All statuses'],...['active','fulfilled','partially_fulfilled','missed','superseded','cancelled'].map(v=>[v,v])],statusFilter)}</div><div class="promise-grid">${promises.length?promises.map(promiseCard).join(''):empty('No commitments in this filter.')}</div>`;}
function promiseCard(p){return `<article class="promise-card"><div class="card-top">${accountLink(inv(p.invoice_id))}${badge(p.status)}</div><div class="promise-amount">${currency(p.amount_minor)}<small>${tx('Promised date')} · ${date(p.promised_date)}</small></div><svg class="progress" viewBox="0 0 300 5" preserveAspectRatio="none" aria-label="${tx('Allocated')}: ${esc(currency(allocated(p)))}"><rect width="300" height="5" rx="2" fill="#e8eeeb"/><rect width="${Math.min(allocated(p)/p.amount_minor,1)*300}" height="5" rx="2" fill="#267867"/></svg><div class="promise-sub"><span>${tx('Allocated')} <strong>${currency(allocated(p))}</strong></span><span>${tx('Remaining')} <strong>${currency(Math.max(p.amount_minor-allocated(p),0))}</strong></span></div>${isActive(p)?`<div class="card-actions">${button('Amend','amend',p.promise_id)}${button('Allocate payment','allocate',p.promise_id)}</div>`:''}<small class="record-id">${esc(p.promise_id)}</small></article>`;}
function taskCard(task){const owner=(state.assignments||[]).find(a=>a.task_id===task.task_id)?.owner;const completion=task.task_type==='balance_check'?button('Run due follow-ups','followups',task.invoice_id):['payment_verification','finance_review','dispute_review'].includes(task.task_type)?button('Review evidence','account',task.invoice_id):button('Complete task','complete-task',task.task_id);return `<article class="task-card"><div class="card-top">${badge(task.task_type)}<span class="subtle">${date(task.due_date)}</span></div><button class="task-customer" data-action="account" data-id="${esc(task.invoice_id)}">${esc(name(inv(task.invoice_id)))}</button><small>${esc(task.invoice_id)}</small><div class="task-owner"><span class="mini-avatar">${esc(teamName(owner).slice(0,1))}</span>${esc(teamName(owner))}${task.status==='pending'?button('Assign owner','assign-task',task.task_id,'text-button'):''}</div>${task.status==='pending'?`<div class="card-actions">${button('View account','account',task.invoice_id,'text-button')}${completion}</div>`:badge(task.status,'green')}</article>`;}
function tasksView(){const tasks=state.tasks.filter(r=>taskOwner==='all'||(state.assignments||[]).find(a=>a.task_id===r.task_id)?.owner===taskOwner);const columns=[['Due now',tasks.filter(t=>t.status==='pending'&&t.due_date<=today())],['Upcoming',tasks.filter(t=>t.status==='pending'&&t.due_date>today())],['Completed',tasks.filter(t=>t.status!=='pending')]];return heading('Team task board','Assign work, review evidence, and close the loop.',`<a class="secondary" href="/api/export?format=csv&dataset=tasks">${tx('Export tasks')}</a>`)+`<div class="toolbar">${filterSelect('taskOwner','Owner',[['all','All'],...(state.team||[]).map(p=>[p.id,localized(p,'name')])],taskOwner)}</div><div class="task-board">${columns.map(([title,items])=>`<section class="task-column"><div class="column-head"><h2>${tx(title)}</h2><span class="count">${num(items.length)}</span></div>${items.length?items.map(taskCard).join(''):empty('No tasks in this column.')}</section>`).join('')}</div>`;}
function draftCard(d){const options=(state.draft_options||[]).find(o=>o.draft_id===d.draft_id)||{};return `<article class="draft-card"><div class="card-top"><div>${accountLink(inv(d.invoice_id))}<div class="draft-tags">${badge(options.purpose||'collection')}${badge(options.language==='ar'?'Arabic':'English')}</div></div>${badge(d.status)}</div><blockquote class="draft-text" dir="auto">${esc(d.text)}</blockquote><div class="draft-footer"><small>${d.approved_by?`${tx('Reviewer')}: ${esc(teamName(d.approved_by))}`:tx('Employee review before delivery')}</small><div class="card-actions">${['awaiting_approval','approved'].includes(d.status)?button('Edit draft','edit-draft',d.draft_id):''}${d.status==='awaiting_approval'?button('Reject','reject-draft',d.draft_id,'text-button')+button('Approve','approve',d.draft_id,'primary'):''}${d.status==='approved'?button('Send to simulated inbox','send',d.draft_id,'primary'):''}</div></div>${d.status==='sent'?`<div class="delivery-proof">${icon('check')}${tx('Delivered to the simulated inbox.')}</div>`:''}</article>`;}
function approvalsView(){const drafts=state.drafts.filter(d=>statusFilter==='all'||d.status===statusFilter);return heading('Review and approve','Every customer-facing draft stays under employee control.')+`<div class="stats three">${stat('Awaiting approval',num(state.drafts.filter(d=>d.status==='awaiting_approval').length),'Employee review before delivery')}${stat('approved',num(state.drafts.filter(d=>d.status==='approved').length),'Sending remains a separate, guarded action.')}${stat('Delivered drafts',num(state.deliveries.length),'Simulated delivery')}</div><div class="toolbar">${filterSelect('statusFilter','Status',[['all','All statuses'],...['awaiting_approval','approved','sent','rejected'].map(v=>[v,v])],statusFilter)}</div><div class="draft-grid">${drafts.length?drafts.slice().reverse().map(draftCard).join(''):empty('No drafts match this filter.')}</div>`;}
function donut(value,total,label){const ratio=total?value/total:0;return `<div class="donut-wrap"><svg viewBox="0 0 120 120" role="img" aria-label="${tx(label)} ${Math.round(ratio*100)}%"><circle cx="60" cy="60" r="47" fill="none" stroke="#e8eeeb" stroke-width="10"/><circle cx="60" cy="60" r="47" fill="none" stroke="#2c7a69" stroke-width="10" stroke-dasharray="${ratio*295.3} 295.3" transform="rotate(-90 60 60)" stroke-linecap="round"/><text x="60" y="64" text-anchor="middle" fill="#193d34" font-size="21" font-weight="600">${Math.round(ratio*100)}%</text></svg><div><strong>${tx(label)}</strong><p>${num(value)} / ${num(total)}</p></div></div>`;}
function analyticsView(){const original=sum(state.invoices,'original_minor'),balance=sum(state.invoices,'outstanding_minor'),fulfilled=state.promises.filter(p=>p.status==='fulfilled').length,eligible=state.promises.filter(p=>['fulfilled','missed','partially_fulfilled'].includes(p.status)).length,processed=state.messages.filter(m=>m.processing_status==='processed').length;return heading('Portfolio intelligence','Metrics calculated from this synthetic workspace, with transparent definitions.')+`<div class="stats">${stat('Invoice value',currency(original),'Synthetic portfolio')}${stat('Balance reduction',currency(original-balance),'Payments and credit adjustments','accent')}${stat('Promise fulfillment',eligible?Math.round(fulfilled/eligible*100)+'%':'—','Recorded fulfilled promises')}${stat('Open disputes',num(state.disputes.filter(d=>['pending_review','pending_credit'].includes(d.status)).length),'Finance review')}</div><div class="overview-grid">${panel('Receivables aging','Days past invoice due date',agingChart())}${panel('Workflow outcomes','Workflow health',`<div class="donut-grid">${donut(processed,state.messages.length,'Message processing')}${donut(state.deliveries.length,state.drafts.length,'Draft delivery')}</div>`)}${panel('Team workload','Open tasks by assigned owner',`<div class="team-workload">${(state.team||[]).map(p=>{const count=state.tasks.filter(t=>t.status==='pending'&&(state.assignments||[]).find(a=>a.task_id===t.task_id)?.owner===p.id).length;return `<div class="workload-row"><span class="avatar">${esc(localized(p,'name').slice(0,1))}</span><div><strong>${esc(localized(p,'name'))}</strong><small>${tx(p.role)}</small></div><span class="count">${num(count)}</span></div>`;}).join('')}</div>`)}${panel('Latest payment allocations','Verified payments',(state.promise_allocations||[]).length?state.promise_allocations.slice(-6).reverse().map(a=>`<div class="commitment-row"><div><strong>${esc(a.payment_reference)}</strong><small>${esc(a.promise_id)}</small></div><strong>${currency(a.amount_minor)}</strong></div>`).join(''):empty('No verified allocations yet.'))}</div>${panel('Metric definitions','',`<ul class="definition-list"><li>${tx('Balance reduction = original invoice value minus current outstanding balance; includes payments and noncash credits.')}</li><li>${tx('Fulfillment = fulfilled / (fulfilled + missed + partially fulfilled). Active and replaced promises excluded.')}</li><li>${tx('These are demonstration metrics, not measured product impact.')}</li></ul>`)}`;}
function feedbackForm(){return `<form data-form="feedback" class="form-stack"><div class="form-two">${selectField('role','Participant role',[['collector','Collector'],['finance','Finance'],['manager','Manager'],['other','Other']],'collector')}${selectField('category','Category',[['usability','Usability'],['missing_capability','Missing capability'],['trust','Trust & accuracy'],['language','Language & clarity'],['value','Would use / value']],'usability')}</div><fieldset class="rating"><legend>${tx('Overall experience')}</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" required><span>${n} ★</span></label>`).join('')}</fieldset>${textField('text','Your feedback','textarea','',true,t('What happened? What would you expect instead?'))}<button class="primary" type="submit">${tx('Submit feedback')}</button></form>`;}
function feedbackView(){const feedback=state.feedback||[];return heading('Help shape Mutabi','Tell us what worked, what was confusing, and what your real workflow needs.',`<div class="header-buttons"><a class="secondary" href="/api/export?format=json">${tx('Export JSON')}</a><a class="secondary" href="/api/export?format=csv">${tx('Export CSV')}</a></div>`)+`<div class="stats three">${stat('Feedback received',num(feedback.length),'Saved to this workspace.')}${stat('Average rating',feedback.length?(sum(feedback,'rating')/feedback.length).toFixed(1)+' / 5':'—','Overall experience')}${stat('Research interactions',num((state.research_events||[]).length),'Research interactions')}</div><div class="feedback-layout">${panel('Give feedback','',feedbackForm())}${panel('Research guide','',`<ol class="research-guide">${['Ask about the most recent late-payment case before showing the product.','Observe whether the participant can review a reply and complete the next action.','Capture workarounds, trust concerns, and willingness to run a concrete pilot.'].map(text=>`<li>${tx(text)}</li>`).join('')}</ol><div class="info-box">${tx('Exports contain this synthetic workspace and feedback only.')}<br>${tx('Exports include synthetic contact references; provider credentials are excluded.')}</div>`)}</div>${panel('Recent feedback','',feedback.length?feedback.slice().reverse().map(f=>`<article class="feedback-record"><div class="card-top"><div>${badge(({usability:'Usability',missing_capability:'Missing capability',trust:'Trust & accuracy',language:'Language & clarity',value:'Would use / value'})[f.category]||f.category)}<span class="subtle">${tx(({collector:'Collector',finance:'Finance',manager:'Manager',other:'Other'})[f.role]||f.role)} · ${tx(f.view==='overview'?'Overview':f.view?f.view.charAt(0).toUpperCase()+f.view.slice(1):'Feedback')}</span></div><strong class="rating-value">${num(f.rating)} ★</strong></div><p dir="auto">${esc(f.text)}</p><small>${date(f.created_at)}</small></article>`).join(''):empty('No feedback yet. Your observations will stay in this workspace.'))}`;}
function providerContent(){const a=state.chatgpt||{accounts:[],models:[]};return `<label class="field"><span>${tx('AI interpretation')}</span><select id="providerChoice"><option value="demo" ${state.provider==='demo'?'selected':''}>${tx('Demo interpreter')}</option><option value="chatgpt_plan" ${state.provider==='chatgpt_plan'?'selected':''}>${tx('ChatGPT plan')}</option><option value="gemini" ${state.provider==='gemini'?'selected':''}>${tx('Gemini API')}</option></select></label><div class="provider-state">${badge(state.model_ready?'Provider ready':'Connection required',state.model_ready?'green':'amber')}<code>${esc(state.provider==='demo'?t(state.model):state.model)}</code></div>${state.provider==='demo'?`<div class="info-box">${tx('Curated examples work without credentials. Free text requires manual review.')}</div>`:state.provider==='gemini'?`<p class="hint">${tx('Gemini uses the locally configured API key.')}</p>`:`<p class="hint">${tx('Eligible requests use your ChatGPT plan allowance after sign-in and permission.')}</p><div class="card-actions">${button(a.pending?'Sign-in in progress…':'Continue with ChatGPT','connect-chatgpt','','primary',a.pending?'disabled':'')}${a.connected?button('Disconnect','chatgpt_disconnect'):''}<a class="text-button" href="https://chatgpt.com/settings/usage" target="_blank" rel="noopener noreferrer">${tx('Manage usage')}</a></div>${(a.accounts||[]).length?`<label class="field"><span>${tx('Account')}</span><select id="chatgptAccount">${a.accounts.map(p=>`<option value="${esc(p.id)}" ${a.active_account===p.id?'selected':''}>${esc(p.label)}</option>`).join('')}</select></label>${button('Add account','add-chatgpt','','text-button')}`:''}${a.connected?`<div class="card-actions">${badge(a.plan_enabled?'Plan usage enabled':'Plan permission disabled')}${button('Refresh models','chatgpt_models')}</div>`:''}${(a.models||[]).length?`<label class="field"><span>${tx('Model')}</span><select id="chatgptModel">${a.models.map(m=>`<option value="${esc(m.slug)}" ${a.model===m.slug?'selected':''}>${esc(m.display_name)}</option>`).join('')}</select></label>`:''}${a.error?`<p class="form-error">${esc(a.error)}</p>`:''}`}`;}
function settingsBaseView(){return heading('Workspace settings','Language, demo identities, provider connections, and policy assumptions.')+`<div class="settings-grid">${panel('Display language','',`<form data-form="preferences" class="form-stack">${selectField('language','Display language',[['en','English'],['ar','Arabic']],language)}${selectField('current_actor','Current reviewer',(state.team||[]).map(p=>[p.id,localized(p,'name')]),actor())}<button class="primary" type="submit">${tx('Save preferences')}</button></form>`)}${panel('AI interpretation','Live AI is optional',providerContent())}${panel('Team identities','Demo identities are assignment labels; they are not access-controlled user accounts.',`<div class="team-workload">${(state.team||[]).map(p=>`<div class="workload-row"><span class="avatar">${esc(localized(p,'name').slice(0,1))}</span><div><strong>${esc(localized(p,'name'))}</strong><small>${tx(p.role)}</small></div></div>`).join('')}</div>`)}${panel('Integrations','',`<div class="integration-list">${[['Accounting','Simulated','Accounting'],['Messaging','Simulated','Simulated delivery'],['CRM','Not connected','Not connected']].map(([title,status,desc])=>`<div class="integration"><span class="integration-icon">${icon(title==='Accounting'?'analytics':title==='Messaging'?'feedback':'collections')}</span><div><strong>${tx(title)}</strong><small>${tx(desc)}</small></div>${badge(status,status==='Simulated'?'green':'')}</div>`).join('')}</div><p class="hint">${tx('Data comes from synthetic accounting events. Delivery is simulated.')}</p>`)}${panel('Policy & assumptions','These assumptions need validation with real operators.',`<div class="policy-list">${['Draft approval required','Accounting balance is authoritative','Human review for disputed or ambiguous replies','One delivery per approved draft'].map(p=>`<div>${icon('check')}<span>${tx(p)}</span></div>`).join('')}</div><details class="assumptions" open><summary>${tx('Product assumptions')}</summary>${(state.assumptions||[]).map(a=>`<article><strong>${esc(localized(a,'title'))}</strong>${badge('Unvalidated','amber')}<p>${esc(localized(a,'description'))}</p><small>${esc(localized(a,'question'))}</small></article>`).join('')}</details>`,'','full-width')}</div>`;}
function studioView(){return heading('Explore the complete workflow','Curated stories for interviews, workshops, and discovery conversations.')+`<div class="story-grid">${(state.stories||[]).map((s,index)=>`<article class="story-card"><span class="story-index">0${index+1}</span><h2>${esc(localized(s,'title'))}</h2><p>${esc(localized(s,'description'))}</p><ol>${storySteps(s).map(step=>`<li>${esc(step)}</li>`).join('')}</ol>${button('Load story','story',s.id,'primary')}</article>`).join('')}</div><div class="settings-grid">${panel('Workspace clock','Date cannot move backwards; reset starts from the baseline.',`<form data-form="clock" class="form-stack">${textField('now','Workspace date','date',today(),true,'',`min="${today()}"`)}<button class="secondary" type="submit">${tx('Advance date')}</button></form>`)}${panel('Accounting sandbox','Record a synthetic payment and verify its accounting evidence.',`<form data-form="simulate-payment" class="form-stack">${selectField('invoice_id','Choose invoice',state.invoices.map(i=>[i.invoice_id,i.invoice_id+' · '+name(i)]))}<div class="form-two">${textField('amount','Amount (SAR)','number','',true,'','min="0.01" step="0.01"')}${textField('reference','Demo payment reference','text','DEMO-'+Date.now().toString().slice(-6),true)}</div>${selectField('promise_id','Optional promise allocation',[['','Do not allocate yet'],...state.promises.filter(isActive).map(p=>[p.promise_id,p.invoice_id+' · '+currency(p.amount_minor)])])}<p class="hint">${tx('Payment is simulated; no bank transaction is created.')}</p><button class="primary" type="submit">${tx('Record payment')}</button></form>`)}${panel('Accounting scenario','',`<form data-form="scenario" class="form-stack">${selectField('scenario','Accounting scenario',[['','Current snapshot'],...(state.accounting_scenarios||[]).map(s=>[s.scenario_id+'|'+s.invoice_id,s.scenario_id+' · '+s.invoice_id+' · '+date(s.available_at)])])}${selectField('invoice_id','Choose invoice',state.invoices.map(i=>[i.invoice_id,i.invoice_id+' · '+name(i)]))}<button class="secondary" type="submit">${tx('Verify scenario')}</button></form>`)}${panel('Import synthetic invoices','',`<form data-form="import-csv" class="form-stack"><label class="field"><span>${tx('Choose CSV file')}</span><input type="file" id="csvFile" accept=".csv,text/csv"></label>${textField('csv_text','CSV data','textarea','invoice_id,customer_id,customer_name,original_amount,outstanding_balance,due_date\nINV-DEMO-101,CUST-DEMO-101,Demo Retail Company,2500,2500,2026-09-15',true)}<label class="checkbox"><input type="checkbox" name="synthetic" required>${tx('I confirm these are synthetic records.')}</label><div class="card-actions"><button class="secondary" type="submit" name="mode" value="preview">${tx('Preview import')}</button><button class="primary" type="submit" name="mode" value="apply">${tx('Apply import')}</button></div></form><div id="importPreview"></div>`)}${panel('Workspace reset','Restart the disposable customer examples. Feedback and research history are retained.',button('Reset workspace','reset','','danger'),'','full-width')}</div>`;}
function textField(name,label,type='text',value='',required=false,placeholder='',extra=''){return `<label class="field"><span>${tx(label)}${required?' <i>*</i>':''}</span>${type==='textarea'?`<textarea name="${name}" ${required?'required':''} placeholder="${esc(placeholder)}" ${extra}>${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}" ${extra}>`}</label>`;}
function settingsView(){return settingsBaseView()+panel('Promise verification timing','Changes affect future checks and delivery guards; existing task dates stay as recorded.',`<form data-form="policy" class="form-stack"><div class="form-three">${textField('followup_days_after_promise','Days after promise','number',state.settings.followup_days_after_promise,true,'','min="1" max="168" step="1"')}${textField('balance_freshness_hours','Balance freshness (hours)','number',state.settings.balance_freshness_hours,true,'','min="1" max="168" step="1"')}${textField('minimum_contact_interval_hours','Minimum contact interval (hours)','number',state.settings.minimum_contact_interval_hours,true,'','min="1" max="168" step="1"')}</div><button class="primary" type="submit">${tx('Save policy')}</button></form>`);}
function storySteps(story){const candidates=language==='ar'?[story.steps_ar,story.steps]:[story.steps];return candidates.find(Array.isArray)||[];}
function selectField(name,label,options,value=''){return `<label class="field"><span>${tx(label)}</span><select name="${name}">${options.map(([v,label])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${tx(label)}</option>`).join('')}</select></label>`;}
function modal(title,content,formName='',help=''){const d=$('actionDialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialogTitle">${tx(title)}</h2><button class="icon-button" data-action="close-action" aria-label="${tx('Close')}">${icon('close')}</button></div>${help?`<p class="dialog-help">${tx(help)}</p>`:''}${formName?`<form data-form="${formName}" class="form-stack">${content}<div class="dialog-actions"><button type="button" class="secondary" data-action="close-action">${tx('Cancel')}</button><button type="submit" class="primary">${tx('Save')}</button></div></form>`:content}`;if(!d.open)d.showModal();}
function renderCustomer(){const invoice=inv(selected);if(!invoice){$('customerDialog').close();return;}const p=profile(invoice),tabs=['conversation','promises','tasks','history'],labels={conversation:'Conversation',promises:'Promises',tasks:'Tasks',history:'Account history'};let content='';
 if(customerTab==='conversation'){const disputes=rows('disputes',selected).filter(d=>['pending_review','pending_credit'].includes(d.status));const verification=rows('tasks',selected).some(t=>t.status==='pending'&&t.task_type==='payment_verification');content=`${disputes.map(d=>`<div class="review-alert"><strong>${tx('Disputed')} · ${badge(d.status)}</strong><p dir="auto">${esc(d.reason)}</p><small>${tx('Claimed amount')}: ${currency(d.claimed_minor)}</small><div class="card-actions">${button('Resolve dispute','resolve-dispute',d.dispute_id)}${d.status==='pending_credit'?button('Simulate credit adjustment','simulate-credit',d.dispute_id):''}</div></div>`).join('')}${verification?`<div class="review-alert"><strong>${tx('Review payment claim')}</strong><p>${tx('Payment evidence is authoritative only after accounting verification.')}</p>${button('Mark verification reviewed','resolve-verification',selected)}</div>`:''}<div class="message-list">${rows('messages',selected).length?rows('messages',selected).map(messageCard).join(''):empty('No replies yet.')}</div><details class="reply-compose"><summary>${tx('New customer reply')}</summary><form data-form="add-reply" class="form-stack">${textField('text','Customer reply','textarea','',true)}<input type="hidden" name="invoice_id" value="${esc(selected)}"><p class="hint">${tx('Free text goes to manual review in demo mode.')}</p><button type="submit" class="primary">${tx('Save reply')}</button></form></details>${panel('Draft text','',rows('drafts',selected).length?rows('drafts',selected).slice().reverse().map(draftCard).join(''):empty('No drafts yet.'),button('Prepare reminder','prepare',selected))}`;}
 if(customerTab==='promises')content=rows('promises',selected).length?rows('promises',selected).map(promiseCard).join(''):empty('No confirmed commitments yet.');
 if(customerTab==='tasks')content=rows('tasks',selected).length?rows('tasks',selected).map(taskCard).join(''):empty('No tasks yet.');
 if(customerTab==='history')content=activityContent(rows('audit_events',selected));
 $('customerDialog').innerHTML=`<div class="customer-top"><div><span class="eyebrow">${tx('Invoice workspace')} · ${esc(selected)}</span><h2 id="customerTitle">${esc(name(invoice))}</h2>${badge(caseStatus(invoice))}</div><button class="icon-button" data-action="close-customer" aria-label="${tx('Close')}">${icon('close')}</button></div><div class="customer-facts"><div><span>${tx('Outstanding balance')}</span><strong>${currency(invoice.outstanding_minor)}</strong></div><div><span>${tx('Original invoice')}</span><strong>${currency(invoice.original_minor)}</strong></div><div><span>${tx('Due date')}</span><strong>${date(invoice.due_date)}</strong></div><div><span>${tx('Balance verified')}</span><strong>${date(invoice.balance_updated_at)}</strong></div></div><div class="customer-actions">${button('Verify current balance','verify',selected)}${button('Run due follow-ups','followups',selected)}${button('Add note','note',selected,'text-button')}</div><div class="customer-layout"><div><div class="tabs" role="tablist" aria-label="${tx('Invoice workspace')}">${tabs.map(id=>`<button role="tab" aria-selected="${customerTab===id}" class="${customerTab===id?'active':''}" data-action="customer-tab" data-id="${id}">${tx(labels[id])}</button>`).join('')}</div><div class="customer-tab-content" role="tabpanel">${content}</div></div><aside class="customer-sidebar"><div class="notes-heading"><h3>${tx('Customer profile')}</h3>${button('Edit','edit-customer',invoice.customer_id,'text-button')}</div><dl>${[['Owner',teamName(p.owner)],['Segment',t(p.segment||'Synthetic portfolio')],['City',language==='ar'?(p.city_ar||t(p.city||'Riyadh')):(p.city||'Riyadh')],['Priority',t(p.priority||'normal')],['Preferred language',t(p.language==='ar'?'Arabic':'English')],['Contact channel',t('Simulated inbox')]].map(([label,value])=>`<dt>${tx(label)}</dt><dd>${esc(value)}</dd>`).join('')}</dl><div class="notes-heading"><h3>${tx('Notes')}</h3>${button('Add note','note',selected,'text-button')}</div>${rows('notes',selected).length?rows('notes',selected).slice().reverse().map(n=>`<div class="note"><p dir="auto">${esc(n.text)}</p><small>${esc(teamName(n.actor))} · ${date(n.created_at)}</small></div>`).join(''):`<p class="hint">${tx('No notes yet.')}</p>`}</aside></div>`;setBusy(busy);
}
function messageCard(m){let interpretation;const audit=state.audit_events.filter(a=>a.action==='message_completed').slice().reverse().find(a=>{try{return JSON.parse(a.details_json).message_id===m.message_id;}catch{return false;}});if(audit){try{interpretation=JSON.parse(audit.details_json);}catch{}}const review=(state.reviews||[]).find(r=>r.message_id===m.message_id),promise=state.promises.find(p=>p.source_message_id===m.message_id);let nextAction=button('Assign invoice','assign-message',m.message_id);if(m.invoice_id)nextAction=promise?(isActive(promise)?button('Amend commitment','amend',promise.promise_id):''):['awaiting_payment_verification','verification_reviewed','dispute_pending_review','dispute_approved','dispute_rejected'].includes(review?.status)?'':button('Confirm commitment','confirm',m.message_id);return `<article class="message"><div class="message-meta"><span>${tx('Customer reply')} · ${esc(m.message_id)}</span><span>${date(m.received_at)}</span></div><p dir="auto">${esc(m.text)}</p>${interpretation?`<details class="interpretation"><summary>${tx('Support evidence')}</summary><pre dir="ltr">${esc(JSON.stringify(interpretation,null,2))}</pre></details>`:''}${review?`<div class="review-summary">${tx(review.status==='confirmed'?'Manual review':'Review result')} · ${esc(t(review.status))} ${review.amount?currency(Math.round(Number(review.amount)*100)):''} ${review.payment_date?date(review.payment_date):''}</div>`:''}<div class="card-actions">${badge(m.processing_status)}${m.processing_status==='pending'?button('Analyze reply','process',m.message_id,'primary'):''}${nextAction}</div></article>`;}
async function act(action,data={},opts={}){if(busy)return null;setBusy(true);try{const response=await fetch('/api/action/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Token':token},body:JSON.stringify(data)});const body=await response.json();if(!response.ok)throw new Error(body.error||t('Could not load workspace'));if(opts.close)$('actionDialog').close();if(action==='story'||action==='reset'){selected=null;$('customerDialog').close();}await refresh();const result=body.result;let message=t('Saved to this workspace.');if(action==='send')message=result.sent?t('Message delivered in simulation.'):t('Sending blocked')+': '+t(result.reason||result.status);if(action==='process'){const labels={promise_recorded:'Promise recorded; follow-up scheduled.',awaiting_clarification:'More detail needed; review the clarification draft.',awaiting_payment_verification:'Payment claim routed to finance verification.',dispute_pending_review:'Dispute routed to finance review.',needs_human_review:'Free-text reply needs manual review.'};message=t(labels[result.status]||'Action completed.');}if(action==='feedback')message=t('Feedback saved. Thank you.');if(action==='simulate_payment')message=t('Synthetic payment recorded.');notice(message,action==='send'&&!result.sent);return result;}catch(error){notice(error.message,true);return null;}finally{setBusy(false);}}
function setBusy(value){busy=value;document.querySelectorAll('button,input,select,textarea').forEach(e=>{if(value){if(e.dataset.wasDisabled===undefined)e.dataset.wasDisabled=e.disabled?'1':'0';e.disabled=true;}else if(e.dataset.wasDisabled!==undefined){e.disabled=e.dataset.wasDisabled==='1';delete e.dataset.wasDisabled;}});document.body.classList.toggle('busy',value);}
let lastViewTime=performance.now();
function navigate(target){const elapsed=Math.round(performance.now()-lastViewTime);recordEvent('view_completed',{view,elapsed_ms:elapsed});lastViewTime=performance.now();view=target;statusFilter='all';render();location.hash=target;$('content').focus({preventScroll:true});recordEvent('view_opened',{view:target});}
async function recordEvent(event,details={}){if(!token)return;try{await fetch('/api/action/event',{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Token':token},body:JSON.stringify({event,view,details})});}catch{}}
function teamOptions(){return (state.team||[]).map(p=>[p.id,localized(p,'name')]);}
function hidden(name,value){return `<input type="hidden" name="${name}" value="${esc(value)}">`;}
document.addEventListener('click',async event=>{const nav=event.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const control=event.target.closest('[data-action]');if(!control||busy)return;const action=control.dataset.action,id=control.dataset.id;
 if(action==='language'){language=language==='ar'?'en':'ar';localStorage.setItem('mutabi-language',language);render();if($('customerDialog').open)renderCustomer();return;}
 if(action==='menu'){const open=$('navigation').classList.toggle('mobile-open');document.querySelector('.mobile-menu').setAttribute('aria-expanded',String(open));if(open)$('navigation').querySelector('.rail-close').focus();else document.querySelector('.mobile-menu').focus();return;}
 if(action==='close-action'){$('actionDialog').close();return;}
 if(action==='close-customer'){$('customerDialog').close();selected=null;return;}
 if(action==='refresh'){try{await refresh();notice(t('Action completed.'));}catch(e){console.error('Workspace refresh failed:',e);notice(e.message,true);}return;}
 if(action==='account'){selected=id;customerTab='conversation';renderCustomer();if(!$('customerDialog').open)$('customerDialog').showModal();recordEvent('customer_opened',{invoice_id:id});return;}
 if(action==='customer-tab'){customerTab=id;renderCustomer();return;}
 if(action==='feedback'){modal('Give feedback',feedbackForm());return;}
 if(action==='note'){modal('Add note',hidden('invoice_id',id)+textField('text','Internal note','textarea','',true),'note');return;}
 if(action==='edit-customer'){const p=state.profiles.find(p=>p.customer_id===id);modal('Customer profile',hidden('customer_id',id)+selectField('language','Preferred language',[['en','English'],['ar','Arabic']],p.language)+selectField('owner','Owner',teamOptions(),p.owner)+selectField('priority','Priority',['normal','high','low'].map(v=>[v,v]),p.priority),'edit-customer');return;}
 if(action==='assign-task'){const owner=(state.assignments||[]).find(a=>a.task_id===id)?.owner;modal('Assign owner',hidden('task_id',id)+selectField('owner','Owner',teamOptions(),owner),'assign-task');return;}
 if(action==='complete-task'){modal('Complete task',hidden('task_id',id)+textField('reason','Completion note','textarea','',true),'complete-task');return;}
 if(action==='assign-message'){const message=state.messages.find(m=>m.message_id===id);modal('Assign invoice',hidden('message_id',id)+selectField('invoice_id','Invoice',state.invoices.filter(i=>i.customer_id===message.customer_id).map(i=>[i.invoice_id,i.invoice_id+' · '+name(i)])),'assign-message','Link the correct invoice before recording a commitment.');return;}
 if(action==='confirm'){const m=state.messages.find(m=>m.message_id===id),i=inv(m.invoice_id),active=rows('promises',m.invoice_id).filter(isActive);modal('Manual review',`<div class="evidence-quote" dir="auto">${esc(m.text)}</div>`+hidden('message_id',id)+`<div class="form-two">${textField('amount','Amount (SAR)','number','',true,'','min="0.01" max="'+(i.outstanding_minor/100)+'" step="0.01"')}${textField('payment_date','Payment date','date',today(),true)}</div>`+selectField('replace_promise_id','Replace existing commitment',[['','New commitment'],...active.map(p=>[p.promise_id,currency(p.amount_minor)+' · '+date(p.promised_date)])])+textField('reason','Reason','textarea','',true),'confirm','Manual review is available for any reply; confirm only details supported by the conversation.');return;}
 if(action==='amend'){const p=state.promises.find(p=>p.promise_id===id);modal('Amend commitment',hidden('promise_id',id)+`<div class="form-two">${textField('amount','Amount (SAR)','number',p.amount_minor/100,true,'','min="0.01" step="0.01"')}${textField('payment_date','Payment date','date',p.promised_date,true)}</div>`+textField('reason','Reason','textarea','',true),'amend','A replacement closes the previous commitment and its scheduled checks.');return;}
 if(action==='allocate'){const p=state.promises.find(p=>p.promise_id===id);modal('Allocate payment',hidden('promise_id',id)+textField('payment_reference','Payment reference','text','',true)+textField('amount','Amount (SAR)','number',Math.max((p.amount_minor-allocated(p))/100,0),true,'','min="0.01" step="0.01"'),'allocate','Use a verified accounting payment reference.');return;}
 if(action==='resolve-dispute'){const d=state.disputes.find(d=>d.dispute_id===id);modal('Resolve dispute',hidden('dispute_id',id)+`<div class="evidence-quote" dir="auto">${esc(d.reason)}</div>`+selectField('resolution','Resolution',d.status==='pending_credit'?[['adjusted','Ledger adjustment verified'],['rejected','Reject dispute']]:[['approved','Accept dispute'],['rejected','Reject dispute']])+textField('reason','Reason','textarea','',true),'resolve-dispute','Review only; this does not automatically alter accounting balances.');return;}
 if(action==='simulate-credit'){const d=state.disputes.find(d=>d.dispute_id===id);modal('Simulate credit adjustment',hidden('invoice_id',d.invoice_id)+textField('amount','Amount (SAR)','number',d.claimed_minor/100,true,'','min="0.01" step="0.01"')+textField('reference','Reference','text','CREDIT-DEMO-'+Date.now().toString().slice(-6),true),'simulate-credit','A credit adjustment reduces receivables without counting as cash payment.');return;}
 if(action==='resolve-verification'){modal('Review payment claim',hidden('invoice_id',id)+textField('reason','Reason','textarea','',true),'resolve-verification','Payment evidence is authoritative only after accounting verification.');return;}
 if(action==='edit-draft'){const d=state.drafts.find(d=>d.draft_id===id),opt=(state.draft_options||[]).find(o=>o.draft_id===id)||{};modal('Edit draft',hidden('draft_id',id)+textField('text','Draft text','textarea',d.text,true)+`<div class="form-two">${selectField('language','Language',[['en','English'],['ar','Arabic']],opt.language||'en')}${selectField('purpose','Purpose',['collection','acknowledgment','verification','dispute'].map(p=>[p,p]),opt.purpose||'collection')}</div>`,'edit-draft','Editing clears any previous approval.');return;}
 if(action==='reject-draft'){modal('Reject draft',hidden('draft_id',id)+textField('reason','Rejection reason','textarea','',true),'reject-draft');return;}
 if(action==='story'){const s=state.stories.find(s=>s.id===id);modal('Replace the demo workspace?',hidden('story_id',id)+`<div class="evidence-quote">${esc(localized(s,'title'))}</div>`,'story','This replaces customer workflows with a fresh story. Your feedback and research history are kept.');return;}
 if(action==='reset'){modal('Start a fresh workspace?',`<p>${tx('Restart the disposable customer examples. Feedback and research history are retained.')}</p>`,'reset');return;}
 if(action==='connect-chatgpt'||action==='add-chatgpt'){connectAuth(action==='add-chatgpt');return;}
 if(action==='process'){const result=await act('process',{message_id:id});if(result?.status==='needs_human_review')recordEvent('manual_review_required',{message_id:id});return;}
 if(action==='approve'||action==='send'){const d=state.drafts.find(d=>d.draft_id===id);await act(action,{draft_id:id,invoice_id:d.invoice_id,actor:actor()});return;}
 if(['verify','followups','prepare'].includes(action)){await act(action,{invoice_id:id,language});return;}
 if(action.startsWith('chatgpt_'))await act(action);
});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(busy)return;const type=form.dataset.form,data=Object.fromEntries(new FormData(form)),close=$('actionDialog').contains(form);let action=type;
 if(type==='feedback'){data.rating=Number(data.rating);data.view=view;action='feedback';}
 if(type==='preferences'){action='settings';data.settings={language:data.language,current_actor:data.current_actor};delete data.language;delete data.current_actor;}
 if(type==='policy'){action='settings';data.settings={followup_days_after_promise:Number(data.followup_days_after_promise),balance_freshness_hours:Number(data.balance_freshness_hours),minimum_contact_interval_hours:Number(data.minimum_contact_interval_hours)};delete data.followup_days_after_promise;delete data.balance_freshness_hours;delete data.minimum_contact_interval_hours;}
 if(type==='note'){action='add_note';data.actor=actor();}
 if(type==='edit-customer')action='update_customer';
 if(type==='assign-task')action='assign_task';
 if(type==='complete-task'){action='complete_task';data.actor=actor();}
 if(type==='assign-message')action='assign_message';
 if(type==='confirm'){action='confirm_message';data.actor=actor();data.replace_promise_id=data.replace_promise_id||null;}
 if(type==='amend'){action='amend_promise';data.actor=actor();}
 if(type==='allocate')action='allocate_payment';
 if(type==='resolve-dispute'){action='resolve_dispute';data.actor=actor();}
 if(type==='simulate-credit'){action='simulate_credit';data.actor=actor();}
 if(type==='resolve-verification'){action='resolve_verification';data.actor=actor();}
 if(type==='edit-draft')action='edit_draft';
 if(type==='reject-draft')action='reject_draft';
 if(type==='add-reply')action='add_reply';
 if(type==='simulate-payment'){action='simulate_payment';data.promise_id=data.promise_id||null;}
 if(type==='clock')data.now+='T10:05:00+03:00';
 if(type==='scenario'){action='verify';if(data.scenario){const [scenario,id]=data.scenario.split('|');data.scenario=scenario;data.invoice_id=id;}else data.scenario=null;}
 if(type==='import-csv'){action='import_csv';data.synthetic=data.synthetic==='on';data.dry_run=event.submitter?.value!=='apply';}
 const result=await act(action,data,{close});
 if(result&&type==='story'&&result.invoice_id){navigate('collections');selected=result.invoice_id;customerTab='conversation';renderCustomer();$('customerDialog').showModal();}
 if(result&&type==='preferences'){language=state.settings.language||language;localStorage.setItem('mutabi-language',language);render();}
 if(result&&type==='import-csv'&&data.dry_run){const importForm=document.querySelector('[data-form="import-csv"]');importForm.elements.csv_text.value=data.csv_text;importForm.elements.synthetic.checked=data.synthetic;$('importPreview').innerHTML=`<div class="info-box"><strong>${tx('Import preview')}: ${num(result.count)}</strong><pre>${esc(JSON.stringify(result.rows,null,2))}</pre></div>`;}
});
document.addEventListener('input',event=>{if(event.target.id==='caseSearch'){const pos=event.target.selectionStart;query=event.target.value;$('viewContent').innerHTML=collectionsView();$('caseSearch').focus();$('caseSearch').setSelectionRange(pos,pos);}});
document.addEventListener('change',async event=>{const id=event.target.id,value=event.target.value;if(id==='caseFilter'){caseFilter=value;$('viewContent').innerHTML=collectionsView();}if(id==='statusFilter'){statusFilter=value;$('viewContent').innerHTML=view==='promises'?promisesView():approvalsView();}if(id==='taskOwner'){taskOwner=value;$('viewContent').innerHTML=tasksView();}if(id==='providerChoice')await act('provider',{provider:value});if(id==='chatgptAccount')await act('chatgpt_account',{account:value});if(id==='chatgptModel')await act('chatgpt_model',{model:value});if(id==='csvFile'&&event.target.files[0]){const file=event.target.files[0];if(file.size>50000){notice(t('CSV data')+': maximum 50 KB',true);return;}const text=await file.text();event.target.form.elements.csv_text.value=text;}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['overview','collections','promises','tasks','approvals','analytics','impact','feedback','settings','studio'].includes(v)&&v!==view){view=v;statusFilter='all';render();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('navigation')?.classList.contains('mobile-open')){$('navigation').classList.remove('mobile-open');const menu=document.querySelector('.mobile-menu');menu.setAttribute('aria-expanded','false');menu.focus();return;}const tabButton=event.target.closest('[role="tab"]');if(!tabButton||busy)return;const keys=['ArrowLeft','ArrowRight','Home','End'];if(!keys.includes(event.key))return;event.preventDefault();const tabs=['conversation','promises','tasks','history'];let index=tabs.indexOf(customerTab);if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else{const forward=(event.key==='ArrowRight')!==(language==='ar');index=(index+(forward?1:-1)+tabs.length)%tabs.length;}customerTab=tabs[index];renderCustomer();$('customerDialog').querySelector(`[data-action="customer-tab"][data-id="${customerTab}"]`).focus();});
async function connectAuth(newAccount){const popup=window.open('about:blank','mutabi-chatgpt-signin');if(!popup){notice(t('Allow the sign-in popup, then try again.'),true);return;}setBusy(true);try{const response=await fetch('/api/action/chatgpt_connect',{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Token':token},body:JSON.stringify({new_account:newAccount})});const body=await response.json();if(!response.ok)throw new Error(body.error);popup.opener=null;popup.location.href=body.result.authorization_url;state.chatgpt.pending=true;notice(t('Complete sign-in in the browser window, then return here.'));pollAuth();}catch(e){popup.close();notice(e.message,true);}finally{setBusy(false);}}
function pollAuth(){if(authPoll)return;authPoll=setInterval(async()=>{try{const response=await fetch('/api/chatgpt');if(!response.ok)return;state.chatgpt=await response.json();if(!state.chatgpt.pending){clearInterval(authPoll);authPoll=null;await refresh();}else if(view==='settings'&&!$('actionDialog').open)render();}catch{}},2500);}
(async()=>{try{const response=await fetch('/api/session');if(!response.ok)throw new Error(t('Could not load workspace'));token=(await response.json()).token;const hash=location.hash.slice(1);if(['overview','collections','promises','tasks','approvals','analytics','impact','feedback','settings','studio'].includes(hash))view=hash;await refresh();recordEvent('workspace_opened',{language});}catch(e){$('app').innerHTML=`<main class="load-error"><h1>${tx('Could not load workspace')}</h1><p>${esc(e.message)}</p><a class="primary" href="/">${tx('Refresh')}</a></main>`;}})();
